      if (row != null) return row; // an id present in BOTH: session_v2 wins
    }
    return undefined;
  }
  let best;
  let bestTable;
  for (const t of tables) {
    const row = db.prepare(sqlSessionNewest(t)).get();
    if (row == null) continue;
    if (best === undefined) {
      best = row;
      bestTable = t;
      continue;
    }
