// read_probe.mjs — scratch probe of the gauge session-row read on fixture DBs
// (scratchpad only; NEVER the live DB). Three shapes: v1 table / v2 table /
// an id present in neither.
import { DatabaseSync } from "node:sqlite";
import { rmSync } from "node:fs";

const G = "C:/Users/Wasiejen/Repos/opencode-agent-v2/.opencode/plugin/scripts/gauge.mjs";
const m = await import(G);

const DIR = "C:/Users/Wasiejen/AppData/Local/Temp/opencode/v2unit1";

function fx(name, stmts) {
  const p = `${DIR}/${name}.db`;
  rmSync(p, { force: true });
  const db = new DatabaseSync(p);
  for (const s of stmts) db.exec(s);
  db.close();
  return p;
}

const v1db = fx("fx_v1", [
  "CREATE TABLE session(id TEXT PRIMARY KEY, model TEXT, time_updated INTEGER)",
  "INSERT INTO session VALUES('ses_v1_fx','plain-v1-model-100K',1000)",
  "CREATE TABLE message(id TEXT, session_id TEXT, data TEXT)",
]);
const v2db = fx("fx_v2", [
  "CREATE TABLE session_v2(id TEXT PRIMARY KEY, model TEXT, time_updated INTEGER)",
  `INSERT INTO session_v2 VALUES('ses_v2_fx','{"id":"fx-v2-model-120K","providerID":"llama-swap"}',2000)`,
]);
const bothdb = fx("fx_both", [
  "CREATE TABLE session(id TEXT PRIMARY KEY, model TEXT, time_updated INTEGER)",
  "INSERT INTO session VALUES('ses_old_fx','old-v1-model-64K',1000)",
  "CREATE TABLE session_v2(id TEXT PRIMARY KEY, model TEXT, time_updated INTEGER)",
  `INSERT INTO session_v2 VALUES('ses_new_fx','{"id":"new-v2-model-170K","providerID":"llama-swap"}',2000)`,
]);

const show = (label, r) => console.log(label, JSON.stringify(r));

show("v1 by id   ", await m.readGauge(v1db, "ses_v1_fx"));
show("v2 by id   ", await m.readGauge(v2db, "ses_v2_fx"));
show("neither    ", await m.readGauge(bothdb, "ses_absent_fx"));
show("both newest", await m.readGauge(bothdb, undefined));
show("no tables  ", await m.readGauge(fx("fx_none", ["CREATE TABLE junk(x INTEGER)"]), "ses_x"));

